import { clamp, lerp } from '../utilities/math.js';

/**
 * Synthesised audio.
 *
 * Every sound in AERODRIVE is generated by the Web Audio API — there are no
 * bundled samples, which means no licensing questions and no download cost. The
 * engine note is a stack of oscillators whose frequency tracks RPM, the tyre and
 * wind layers are filtered noise whose gain tracks speed and slip, and impacts
 * are shaped noise bursts.
 *
 * Architecture notes that matter for performance and correctness:
 *  - **One long-lived node graph.** Sources are created once and their gains
 *    modulated per frame. Creating oscillators every frame is a well-known way to
 *    make a browser audio thread crackle and leak.
 *  - **Autoplay compliance.** `unlock()` must be called from a real user gesture;
 *    until then the context stays suspended and every call is a safe no-op.
 *  - **Voice budget.** The preset caps how many layers are active, so a Potato
 *    machine runs engine + tyres only.
 *  - **Headroom.** Each bus feeds a compressor before the master gain so that
 *    several loud layers cannot clip into distortion.
 */

/** Two seconds of white noise, reused by every noise-based layer. */
function createNoiseBuffer(context, seconds = 2) {
  const length = Math.floor(context.sampleRate * seconds);
  const buffer = context.createBuffer(1, length, context.sampleRate);
  const data = buffer.getChannelData(0);
  // Deterministic PRNG: an identical noise bed every run.
  let state = 0x1f2e3d4c;
  for (let i = 0; i < length; i++) {
    state = (state * 1664525 + 1013904223) >>> 0;
    data[i] = (state / 2147483648 - 1) * 0.85;
  }
  return buffer;
}

const AMBIENCE_PROFILES = {
  forest: { type: 'bandpass', frequency: 1400, q: 0.7, gain: 0.05, lfo: 0.14 },
  coastal: { type: 'lowpass', frequency: 700, q: 0.6, gain: 0.07, lfo: 0.09 },
  city: { type: 'lowpass', frequency: 420, q: 0.7, gain: 0.06, lfo: 0.07 },
  desert: { type: 'bandpass', frequency: 900, q: 0.5, gain: 0.04, lfo: 0.05 },
};

export class AudioEngine {
  /** @param {{get:(key:string)=>any}} settings */
  constructor({ settings }) {
    this.settings = settings;
    this.context = null;
    this.ready = false;
    this.enabled = true;

    this.noiseBuffer = null;
    this.buses = null;
    this.nodes = null;
    this.state = {
      rpm: 0,
      speed: 0,
      slip: 0,
      load: 0,
      surface: 'asphalt',
      airborne: false,
      gear: 0,
      engineRunning: false,
    };
    this._engineProfile = { cylinders: 4, noteOffset: 0, idleGain: 0.26, maxGain: 0.6 };
    this._lastGear = 0;
    this._impactCooldown = 0;
    this._positional = new Map();
    this._rich = false;
    this._masterLevel = 0.6;
    this._ambienceTarget = undefined;
  }

  /** True once the context exists and is running. */
  get unlocked() {
    return Boolean(this.context && this.context.state === 'running');
  }

  /**
   * Create/resume the audio context. MUST be called from a user gesture
   * (click, keydown) or browsers will leave it suspended.
   */
  async unlock() {
    if (this.ready) {
      if (this.context.state === 'suspended') {
        try {
          await this.context.resume();
        } catch {
          /* still locked; harmless */
        }
      }
      return this.ready;
    }

    const AudioContextClass = window.AudioContext ?? window.webkitAudioContext;
    if (!AudioContextClass) {
      console.warn('[Audio] Web Audio API unavailable; running silent.');
      this.enabled = false;
      return false;
    }

    try {
      this.context = new AudioContextClass({ latencyHint: 'interactive' });
      this.noiseBuffer = createNoiseBuffer(this.context);
      this._buildGraph();
      if (this.context.state === 'suspended') await this.context.resume();
      this.ready = true;
      this.applySettings(this.settings);
      return true;
    } catch (error) {
      console.warn('[Audio] Could not start audio:', error.message);
      this.enabled = false;
      return false;
    }
  }

  _buildGraph() {
    const context = this.context;

    // Master chain with a limiter so overlapping layers cannot clip.
    this.masterGain = context.createGain();
    this.compressor = context.createDynamicsCompressor();
    this.compressor.threshold.value = -12;
    this.compressor.knee.value = 24;
    this.compressor.ratio.value = 8;
    this.compressor.attack.value = 0.004;
    this.compressor.release.value = 0.22;
    this.masterGain.connect(this.compressor);
    this.compressor.connect(context.destination);

    const makeBus = (volume) => {
      const gain = context.createGain();
      gain.gain.value = volume;
      gain.connect(this.masterGain);
      return gain;
    };
    this.buses = {
      engine: makeBus(0.7),
      effects: makeBus(0.7),
      ambience: makeBus(0.5),
      ui: makeBus(0.6),
    };

    this.nodes = this._buildEngineVoices();
    this.nodes.tyre = this._buildNoiseVoice({
      bus: this.buses.effects,
      filterType: 'bandpass',
      frequency: 1100,
      q: 1.1,
      gain: 0,
    });
    this.nodes.screech = this._buildNoiseVoice({
      bus: this.buses.effects,
      filterType: 'highpass',
      frequency: 2400,
      q: 2.4,
      gain: 0,
    });
    this.nodes.wind = this._buildNoiseVoice({
      bus: this.buses.effects,
      filterType: 'lowpass',
      frequency: 520,
      q: 0.6,
      gain: 0,
    });
    this.nodes.ambience = this._buildNoiseVoice({
      bus: this.buses.ambience,
      filterType: 'bandpass',
      frequency: 1200,
      q: 0.7,
      gain: 0,
    });
    // Rain on the bodywork. Kept on the effects bus rather than the ambience bus
    // so the ambience slider does not turn the weather off.
    this.nodes.rain = this._buildNoiseVoice({
      bus: this.buses.effects,
      filterType: 'bandpass',
      frequency: 2400,
      q: 0.5,
      gain: 0,
    });
  }

  /** Engine = two detuned saw oscillators through a tracking low-pass, plus induction noise. */
  _buildEngineVoices() {
    const context = this.context;

    const filter = context.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 900;
    filter.Q.value = 3.2;

    const engineGain = context.createGain();
    engineGain.gain.value = 0;
    filter.connect(engineGain);
    engineGain.connect(this.buses.engine);

    const tone = context.createGain();
    tone.gain.value = 0.55;
    tone.connect(filter);

    const fundamental = context.createOscillator();
    fundamental.type = 'sawtooth';
    fundamental.frequency.value = 40;
    fundamental.connect(tone);

    // A slightly detuned partial and a sub-octave give the note body; without
    // them a sawtooth alone sounds like a test tone rather than an engine.
    const partial = context.createOscillator();
    partial.type = 'square';
    partial.frequency.value = 60;
    partial.detune.value = 14;
    const partialGain = context.createGain();
    partialGain.gain.value = 0.28;
    partial.connect(partialGain);
    partialGain.connect(filter);

    const sub = context.createOscillator();
    sub.type = 'sine';
    sub.frequency.value = 20;
    const subGain = context.createGain();
    subGain.gain.value = 0.32;
    sub.connect(subGain);
    subGain.connect(filter);

    const induction = context.createBufferSource();
    induction.buffer = this.noiseBuffer;
    induction.loop = true;
    const inductionFilter = context.createBiquadFilter();
    inductionFilter.type = 'bandpass';
    inductionFilter.frequency.value = 320;
    inductionFilter.Q.value = 0.9;
    const inductionGain = context.createGain();
    inductionGain.gain.value = 0;
    induction.connect(inductionFilter);
    inductionFilter.connect(inductionGain);
    inductionGain.connect(this.buses.engine);

    fundamental.start();
    partial.start();
    sub.start();
    induction.start();

    return {
      engine: { fundamental, partial, sub, filter, gain: engineGain, tone, partialGain, subGain },
      induction: { source: induction, gain: inductionGain, filter: inductionFilter },
    };
  }

  _buildNoiseVoice({ bus, filterType, frequency, q, gain }) {
    const context = this.context;
    const source = context.createBufferSource();
    source.buffer = this.noiseBuffer;
    source.loop = true;

    const filter = context.createBiquadFilter();
    filter.type = filterType;
    filter.frequency.value = frequency;
    filter.Q.value = q;

    const gainNode = context.createGain();
    gainNode.gain.value = gain;

    source.connect(filter);
    filter.connect(gainNode);
    gainNode.connect(bus);
    source.start();

    return { source, filter, gain: gainNode };
  }

  /* ------------------------------- controls ------------------------------- */

  applySettings(settings) {
    this.settings = settings;
    if (!this.ready) return;
    const master = clamp((settings.masterVolume ?? 80) / 100, 0, 1);
    this._masterLevel = master * master; // perceptual-ish curve
    this.masterGain.gain.value = this._masterLevel;
    this.buses.engine.gain.value = clamp((settings.engineVolume ?? 75) / 100, 0, 1);
    this.buses.effects.gain.value = clamp((settings.effectsVolume ?? 70) / 100, 0, 1);
    this.buses.ambience.gain.value = clamp((settings.ambienceVolume ?? 55) / 100, 0, 1);

    // Voice budget: on Potato/Low the disposable layers (screech, gearshift
    // flourishes, extra traffic voices) are switched off entirely.
    this._rich = settings.preset === 'medium' || settings.preset === 'high';
    if (this.nodes) {
      this.nodes.wind.source.playbackRate.value = this._rich ? 1 : 0.85;
    }
  }

  /** Switch the engine note to match a vehicle definition. */
  setEngineProfile(audioConfig) {
    if (!audioConfig) return;
    this._engineProfile = { ...this._engineProfile, ...audioConfig };
  }

  /** Ambience bed for a map. */
  setAmbience(profileName) {
    if (!this.ready) return;
    const profile = AMBIENCE_PROFILES[profileName] ?? AMBIENCE_PROFILES.forest;
    const node = this.nodes.ambience;
    node.filter.type = profile.type;
    node.filter.frequency.value = profile.frequency;
    node.filter.Q.value = profile.q;
    this._ambienceTarget = profile.gain;
  }

  /**
   * Per-frame update. All values are read from the vehicle telemetry, so this is
   * a pure mapping from simulation state to audio parameters.
   *
   * @param {number} dt
   * @param {object} telemetry Vehicle telemetry
   * @param {object} options
   */
  update(dt, telemetry, { preset = 'low' } = {}) {
    if (!this.ready || !this.enabled) return;
    this._impactCooldown = Math.max(0, this._impactCooldown - dt);
    if (!telemetry) return;

    const rich = preset === 'medium' || preset === 'high';
    const { cylinders, noteOffset, idleGain, maxGain } = this._engineProfile;

    const rpm = clamp(telemetry.rpm ?? 0, 0, 9000);
    const load = clamp(telemetry.throttle ?? 0, 0, 1);
    const speed = clamp(telemetry.speedKmh ?? 0, 0, 400);
    const slip = clamp(telemetry.wheelSlip ?? 0, 0, 1);
    const airborne = Boolean(telemetry.airborne);

    // Firing frequency of the engine: rpm/60 revolutions per second, times half
    // the cylinder count (a four-stroke fires each cylinder every other turn).
    const baseFrequency = (rpm / 60) * Math.max(1, cylinders / 2);
    const semitone = 2 ** (noteOffset / 12);
    const fundamental = clamp(baseFrequency * semitone, 12, 900);

    const engine = this.nodes.engine;
    const now = this.context.currentTime;
    // 30 ms time constants: fast enough to hear every gearshift, slow enough to
    // avoid zipper noise.
    engine.fundamental.frequency.setTargetAtTime(fundamental, now, 0.03);
    engine.partial.frequency.setTargetAtTime(fundamental * 1.5, now, 0.03);
    engine.sub.frequency.setTargetAtTime(fundamental * 0.5, now, 0.03);

    const targetCutoff = clamp(400 + (rpm / 9000) * 4200 + load * 900, 300, 7000);
    engine.filter.frequency.setTargetAtTime(targetCutoff, now, 0.05);

    // Engine gain: idle plus load, muted while airborne (no wheels driving it)
    // and during gearshifts, which is what makes a shift audible.
    const idleLevel = idleGain * (0.7 + 0.3 * load);
    const loadLevel = maxGain * load;
    const targetGain = airborne
      ? idleLevel * 0.4
      : lerp(idleLevel, loadLevel, clamp(rpm / 6000, 0, 1));
    engine.gain.gain.setTargetAtTime(clamp(targetGain, 0, 0.9), now, 0.06);
    engine.tone.gain.setTargetAtTime(0.4 + load * 0.35, now, 0.08);

    this.nodes.induction.gain.gain.setTargetAtTime(load * 0.09, now, 0.07);
    this.nodes.induction.filter.frequency.setTargetAtTime(200 + rpm * 0.06, now, 0.08);

    // --- Tyres -----------------------------------------------------------
    const surfaceFactor =
      telemetry.onSurface === 'asphalt'
        ? 1
        : telemetry.onSurface === 'dirt'
          ? 1.35
          : telemetry.onSurface === 'grass'
            ? 1.5
            : 1.2;
    const rolling = airborne ? 0 : clamp(speed / 190, 0, 1) * 0.16 * surfaceFactor;
    this.nodes.tyre.gain.gain.setTargetAtTime(rolling, now, 0.08);
    this.nodes.tyre.filter.frequency.setTargetAtTime(
      700 + surfaceFactor * 600 + speed * 3.2,
      now,
      0.1,
    );

    // Screech only on richer presets: it is the most disposable layer.
    const screechGain = rich && !airborne ? clamp(slip * 0.24, 0, 0.24) : 0;
    this.nodes.screech.gain.gain.setTargetAtTime(screechGain, now, 0.05);

    // --- Wind ------------------------------------------------------------
    const wind = clamp((speed / 300) ** 2, 0, 1) * 0.14;
    this.nodes.wind.gain.gain.setTargetAtTime(wind, now, 0.15);

    // --- Ambience --------------------------------------------------------
    if (this._ambienceTarget !== undefined) {
      this.nodes.ambience.gain.gain.setTargetAtTime(this._ambienceTarget, now, 0.5);
    }

    this.state.rpm = rpm;
    this.state.speed = speed;
    this.state.slip = slip;
    this.state.load = load;
    this.state.gear = telemetry.gear ?? 0;
    this.state.airborne = airborne;
    this.state.surface = telemetry.onSurface ?? 'asphalt';
  }

  /** Gearshift blip. */
  gearShift(up = true) {
    if (!this.ready || !this._rich) return;
    this._blip(up ? 220 : 160, 0.05, 'triangle', 0.12);
  }

  /** Short dual-tone horn blast. */
  horn() {
    if (!this.ready) return;
    const context = this.context;
    const now = context.currentTime;
    const envelope = context.createGain();
    const filter = context.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 1900;
    filter.Q.value = 0.7;

    envelope.gain.setValueAtTime(0.0001, now);
    envelope.gain.exponentialRampToValueAtTime(0.2, now + 0.015);
    envelope.gain.setValueAtTime(0.2, now + 0.28);
    envelope.gain.exponentialRampToValueAtTime(0.0001, now + 0.42);
    filter.connect(envelope);
    envelope.connect(this.buses.effects);

    let remaining = 2;
    for (const frequency of [415, 523]) {
      const oscillator = context.createOscillator();
      oscillator.type = 'square';
      oscillator.frequency.value = frequency;
      oscillator.connect(filter);
      oscillator.start(now);
      oscillator.stop(now + 0.45);
      oscillator.onended = () => {
        oscillator.disconnect();
        remaining -= 1;
        if (remaining === 0) {
          filter.disconnect();
          envelope.disconnect();
        }
      };
    }
  }

  /** Collision thump, strength 0..1. */
  impact(strength = 0.5) {
    if (!this.ready) return;
    if (this._impactCooldown > 0) return;
    this._impactCooldown = 0.09;
    const amount = clamp(strength, 0, 1);
    this._noiseBurst({
      duration: 0.28,
      gain: 0.08 + amount * 0.32,
      filterType: 'lowpass',
      startFrequency: 320 + amount * 900,
      endFrequency: 70,
      bus: this.buses.effects,
    });
  }

  /** Suspension/kerb thump. */
  suspensionHit(strength = 0.4) {
    if (!this.ready) return;
    this._noiseBurst({
      duration: 0.14,
      gain: 0.04 + clamp(strength, 0, 1) * 0.14,
      filterType: 'lowpass',
      startFrequency: 180,
      endFrequency: 60,
      bus: this.buses.effects,
    });
  }

  /**
   * Distant thunder.
   *
   * Only the rumble is synthesised, not a sharp crack: the strike itself is
   * silent from a driver's distance, which is what makes the delay between the
   * flash and the sound read as distance rather than as lag.
   */
  thunder() {
    if (!this.ready) return;
    this._noiseBurst({
      duration: 2.6,
      gain: 0.32,
      filterType: 'lowpass',
      startFrequency: 260,
      endFrequency: 40,
      bus: this.buses.effects,
    });
    this._blip(54, 1.7, 'sine', 0.09);
  }

  /**
   * Rain on the bodywork.
   *
   * A separate filtered-noise voice whose gain tracks the weather, so rain is
   * audible standing still as well as at speed — and it layers with the wind
   * noise rather than replacing it.
   *
   * @param {number} amount 0 (dry) to 1 (pouring).
   */
  setRain(amount) {
    if (!this.ready) return;
    const level = clamp(amount, 0, 1);
    // Ratio of 0 stands the voice down completely, so removing the node's gain
    // is not necessary to stop it costing anything meaningful.
    this.nodes.rain.gain.gain.setTargetAtTime(level * 0.075, this.context.currentTime, 0.6);
    this.nodes.rain.filter.frequency.setTargetAtTime(
      1800 + level * 2600,
      this.context.currentTime,
      0.5,
    );
  }

  /** UI feedback: 'move' | 'confirm' | 'back' | 'error'. */
  ui(kind = 'move') {
    if (!this.ready) return;
    const table = {
      move: { frequency: 520, duration: 0.05, type: 'sine', gain: 0.1 },
      confirm: { frequency: 780, duration: 0.09, type: 'triangle', gain: 0.14 },
      back: { frequency: 320, duration: 0.08, type: 'sine', gain: 0.1 },
      error: { frequency: 180, duration: 0.16, type: 'square', gain: 0.1 },
      unlock: { frequency: 660, duration: 0.22, type: 'triangle', gain: 0.16 },
      checkpoint: { frequency: 980, duration: 0.12, type: 'square', gain: 0.12 },
    };
    const spec = table[kind] ?? table.move;
    // A two-step chime reads as "success" far better than a single tone.
    this._blip(spec.frequency, spec.duration, spec.type, spec.gain, this.buses.ui);
    if (kind === 'confirm' || kind === 'unlock') {
      setTimeout(
        () => this._blip(spec.frequency * 1.5, spec.duration, spec.type, spec.gain, this.buses.ui),
        90,
      );
    }
  }

  _blip(frequency, duration, type = 'sine', gain = 0.12, bus = null) {
    if (!this.ready) return;
    const context = this.context;
    const oscillator = context.createOscillator();
    oscillator.type = type;
    oscillator.frequency.value = frequency;
    const envelope = context.createGain();
    envelope.gain.setValueAtTime(0.0001, context.currentTime);
    envelope.gain.exponentialRampToValueAtTime(gain, context.currentTime + 0.008);
    envelope.gain.exponentialRampToValueAtTime(0.0001, context.currentTime + duration);
    oscillator.connect(envelope);
    envelope.connect(bus ?? this.buses.effects);
    oscillator.start();
    oscillator.stop(context.currentTime + duration + 0.02);
    // Nodes are short-lived by design here (a handful per minute), so the GC
    // pressure is negligible and the code stays simple.
    oscillator.onended = () => {
      oscillator.disconnect();
      envelope.disconnect();
    };
  }

  _noiseBurst({ duration, gain, filterType, startFrequency, endFrequency, bus }) {
    const context = this.context;
    const source = context.createBufferSource();
    source.buffer = this.noiseBuffer;
    source.loop = true;
    const filter = context.createBiquadFilter();
    filter.type = filterType;
    filter.frequency.setValueAtTime(startFrequency, context.currentTime);
    filter.frequency.exponentialRampToValueAtTime(
      Math.max(30, endFrequency),
      context.currentTime + duration,
    );
    const envelope = context.createGain();
    envelope.gain.setValueAtTime(0.0001, context.currentTime);
    envelope.gain.exponentialRampToValueAtTime(gain, context.currentTime + 0.012);
    envelope.gain.exponentialRampToValueAtTime(0.0001, context.currentTime + duration);
    source.connect(filter);
    filter.connect(envelope);
    envelope.connect(bus);
    source.start();
    source.stop(context.currentTime + duration + 0.05);
    source.onended = () => {
      source.disconnect();
      filter.disconnect();
      envelope.disconnect();
    };
  }

  /**
   * Attach a positional engine source to a traffic vehicle.
   * Uses a PannerNode so distant traffic is heard from its actual direction,
   * with distance attenuation and a limited voice count on low presets.
   */
  attachPositionalVehicle(id, audioConfig = {}) {
    if (!this.ready) return null;
    if (!this._rich && this._positional.size >= 4) return null;

    const context = this.context;
    const oscillator = context.createOscillator();
    oscillator.type = 'sawtooth';
    oscillator.frequency.value = 55;

    const gain = context.createGain();
    gain.gain.value = 0;

    const panner = context.createPanner();
    panner.panningModel = 'equalpower'; // cheaper than HRTF, fine for traffic
    panner.distanceModel = 'inverse';
    panner.refDistance = 6;
    panner.maxDistance = 140;
    panner.rolloffFactor = 1.6;

    oscillator.connect(gain);
    gain.connect(panner);
    panner.connect(this.buses.effects);
    oscillator.start();

    const handle = {
      oscillator,
      gain,
      panner,
      profile: { cylinders: 4, noteOffset: 0, ...audioConfig },
      dispose: () => {
        try {
          oscillator.stop();
        } catch {
          /* already stopped */
        }
        oscillator.disconnect();
        gain.disconnect();
        panner.disconnect();
        this._positional.delete(id);
      },
    };
    this._positional.set(id, handle);
    return handle;
  }

  /** Update a positional traffic source's pitch/level/position. */
  updatePositionalVehicle(id, { position, rpm = 900, load = 0.2 }) {
    const handle = this._positional.get(id);
    if (!handle) return;
    const now = this.context.currentTime;
    const semitone = 2 ** ((handle.profile.noteOffset ?? 0) / 12);
    const frequency = clamp((rpm / 60) * ((handle.profile.cylinders ?? 4) / 2) * semitone, 15, 700);
    handle.oscillator.frequency.setTargetAtTime(frequency, now, 0.08);
    handle.gain.gain.setTargetAtTime(0.02 + load * 0.14, now, 0.12);
    if (handle.panner.positionX) {
      handle.panner.positionX.setTargetAtTime(position.x, now, 0.05);
      handle.panner.positionY.setTargetAtTime(position.y, now, 0.05);
      handle.panner.positionZ.setTargetAtTime(position.z, now, 0.05);
    } else {
      // Safari historically lacked the AudioParam panner positions.
      handle.panner.setPosition(position.x, position.y, position.z);
    }
  }

  detachPositionalVehicle(id) {
    this._positional.get(id)?.dispose();
  }

  /** Update the global listener transform so positional audio is correct. */
  updateListener(position, quaternion) {
    if (!this.ready) return;
    const listener = this.context.listener;
    const now = this.context.currentTime;
    if (listener.positionX) {
      listener.positionX.setTargetAtTime(position.x, now, 0.02);
      listener.positionY.setTargetAtTime(position.y, now, 0.02);
      listener.positionZ.setTargetAtTime(position.z, now, 0.02);
      // Forward is +Z in the chassis frame (see Vehicle), so the listener
      // forward vector comes from the camera quaternion applied to (0,0,1).
      const forward = { x: 0, y: 0, z: 1 };
      const up = { x: 0, y: 1, z: 0 };
      const f = rotate(forward, quaternion);
      const u = rotate(up, quaternion);
      listener.forwardX.setTargetAtTime(f.x, now, 0.02);
      listener.forwardY.setTargetAtTime(f.y, now, 0.02);
      listener.forwardZ.setTargetAtTime(f.z, now, 0.02);
      listener.upX.setTargetAtTime(u.x, now, 0.02);
      listener.upY.setTargetAtTime(u.y, now, 0.02);
      listener.upZ.setTargetAtTime(u.z, now, 0.02);
    } else {
      listener.setPosition(position.x, position.y, position.z);
    }
  }

  /** Silence everything (pause menu, tab hidden) without losing the volume setting. */
  setMuted(muted) {
    if (!this.ready) return;
    const target = muted ? 0 : this._masterLevel;
    this.masterGain.gain.setTargetAtTime(target, this.context.currentTime, 0.05);
  }

  /** Called when the tab is hidden: browsers suspend audio anyway, but silence
   *  prevents a burst of stale sound when it comes back. */
  suspend() {
    if (this.ready && this.context.state === 'running') this.context.suspend().catch(() => {});
  }

  resume() {
    if (this.ready && this.context.state === 'suspended') this.context.resume().catch(() => {});
  }

  dispose() {
    for (const id of [...this._positional.keys()]) this.detachPositionalVehicle(id);
    if (this.context) {
      this.context.close().catch(() => {});
      this.context = null;
    }
    this.ready = false;
    this.enabled = false;
  }
}

/** Rotate a vector by a quaternion ({x,y,z,w}). */
function rotate(vector, quaternion) {
  const { x, y, z, w } = quaternion;
  const ix = w * vector.x + y * vector.z - z * vector.y;
  const iy = w * vector.y + z * vector.x - x * vector.z;
  const iz = w * vector.z + x * vector.y - y * vector.x;
  const iw = -x * vector.x - y * vector.y - z * vector.z;
  return {
    x: ix * w + iw * -x + iy * -z - iz * -y,
    y: iy * w + iw * -y + iz * -x - ix * -z,
    z: iz * w + iw * -z + ix * -y - iy * -x,
  };
}
